#!/usr/bin/env bash
# creature-word-bomb-sfx.sh — concrete poetry glitchfest WITH chiptune SFX
#
# v2 of creature-word-bomb.sh:
# - Uses wibwob CLI syntax (not curl/JSON) for all commands
# - Plays chiptune SFX hits synced to each visual event
# - SFX generated by gen-sfx.py (run first if sfx/ dir missing)
#
# DEV NOTE: shell command ergonomics
# ────────────────────────────────────
# PREFER this (CLI syntax):
#   wibwob primer.open --filePath "/path/file.txt" --x 5 --y 3
#   wibwob figlet.open --text "HELLO" --font doom
#   wibwob cmd desktop.clear-all
#   wibwob theme.set --name wibwob-phosphor
#   wibwob screenshot > capture.txt
#
# AVOID this (raw curl/JSON — only needed for /windows/batch):
#   curl -s -X POST $API/commands/run -H '...' -d '{"id":"primer.open","args":{...}}'
#
# SFX playback:
#   sfx "path.wav"              — fire-and-forget (backgrounds ffplay)
#   sfx "path.wav" && sleep N   — sound + pause for human eye
#
# Batch positioning (no CLI verb yet, curl required):
#   wibwob windows | jq '[...build ops...]' | curl ... -d @-
#
# MP3 files also work: sfx "path.mp3"
# Any audio ffplay can handle works as an SFX source.
#
# FLAGS:
#   --record     Wrap in asciinema recording → .cast file
#   --export     After recording, render .cast → .gif + mix audio → .mp3 → .mp4
#   --render-audio  Just render the SFX mix to .mp3 (no visual run)

set -e
cd "$(dirname "$0")/../.."

# ── Parse flags ──
DO_RECORD=false
DO_EXPORT=false
RENDER_AUDIO_ONLY=false
for arg in "$@"; do
  case "$arg" in
    --record) DO_RECORD=true ;;
    --export) DO_RECORD=true; DO_EXPORT=true ;;
    --render-audio) RENDER_AUDIO_ONLY=true ;;
  esac
done

W="bun run src/cli/wibwob.ts"
SMEAR="python3 .pi/skills/vj-timeline/scripts/smear.py"
DIR="scratch/captures/wordbomb-sfx-$(date +%s)"
mkdir -p "$DIR"
API="http://127.0.0.1:8099"
SFX="scratch/cli-experiments/sfx"
JGS="/Users/james/Repos/symbient-skills/skills/joan-stark-ascii-art/examples"
CUES_FILE="$DIR/cues.tsv"
START_TIME=""
WW="microapps-private/wibwob-primers/primers"

# Generate SFX if missing
if [ ! -f "$SFX/hit-word.wav" ]; then
  echo "Generating SFX..."
  REPO_ROOT="$PWD" uv run scratch/cli-experiments/gen-sfx.py "$SFX"
fi
if [ ! -f "$SFX/boom-cartoon.wav" ]; then
  echo "Generating explosion SFX..."
  REPO_ROOT="$PWD" uv run scratch/cli-experiments/gen-explosions.py "$SFX"
fi
if [ ! -f "$SFX/hit-arrange.wav" ]; then
  echo "Generating arrange SFX..."
  REPO_ROOT="$PWD" uv run scratch/cli-experiments/gen-arrange.py "$SFX"
fi
if [ ! -f "$SFX/fin-melody.wav" ]; then
  echo "Generating fin melody..."
  REPO_ROOT="$PWD" uv run scratch/cli-experiments/gen-fin-melody.py "$SFX"
fi

# Pre-render voice lines as WAV (say -o renders to file, then convert)
VOICE_DIR="$SFX/voice"
mkdir -p "$VOICE_DIR"
render_voice() {
  local voice="$1" text="$2" name="$3"
  local wav="$VOICE_DIR/${name}.wav"
  if [ ! -f "$wav" ]; then
    say -v "$voice" "$text" -o "$VOICE_DIR/${name}.aiff"
    ffmpeg -y -i "$VOICE_DIR/${name}.aiff" "$wav" 2>/dev/null
    rm -f "$VOICE_DIR/${name}.aiff"
  fi
}
render_voice "Samantha" "wib" "v-wib"
render_voice "Daniel" "wob" "v-wob"
render_voice "Wobble" "presents" "v-presents"
render_voice "Zarvox" "the menagerie" "v-menagerie"
render_voice "Bad News" "corruption" "v-corruption"
render_voice "Whisper" "shear" "v-shear"
render_voice "Trinoids" "deep glitch" "v-deep-glitch"
render_voice "Boing" "the word bomb" "v-word-bomb"
render_voice "Bells" "destruction" "v-destruction"
render_voice "Cellos" "fin" "v-fin"

# SFX player — also logs timestamp + path to cues.tsv for audio rendering
epoch_ms() { python3 -c "import time; print(int(time.time()*1000))"; }
sfx() {
  ffplay -nodisp -autoexit "$1" 2>/dev/null &
  # Log cue for offline mix
  if [ -n "$START_TIME" ]; then
    NOW=$(epoch_ms)
    OFFSET=$(( NOW - START_TIME ))
    echo -e "${OFFSET}\t${1}" >> "$CUES_FILE"
  fi
}

# Batch position helper — still needs curl (no CLI batch verb)
batch() { curl -s -X POST "$API/windows/batch" -H 'Content-Type: application/json' -d "$1" >/dev/null; }

# ── Render audio only mode ──
if [ "$RENDER_AUDIO_ONLY" = true ] && [ -f "$2" ]; then
  echo "Rendering audio from cues: $2"
  uv run scratch/cli-experiments/mix-sfx-track.py "$2" "$DIR/soundtrack.mp3"
  exit 0
fi

# ── Start asciinema recording if requested ──
if [ "$DO_RECORD" = true ]; then
  CAST_FILE="$DIR/recording.cast"
  echo "Recording with asciinema → $CAST_FILE"
  # Re-exec ourselves inside asciinema, without --record to avoid recursion
  exec asciinema rec "$CAST_FILE" -c "bash $0"
fi

