# Wave 2 — crackle + zap
sfx "$SFX/boom-crackle.wav"
sfx "$SFX/boom-zap.wav"
sleep 0.05
IDX=0; SKIP=0
for id in $ALL_WIN; do
  SKIP=$((SKIP + 1))
  [ $SKIP -le $THIRD ] && continue
  [ $IDX -ge $THIRD ] && break
  $W window $id close 2>&1 >/dev/null
  IDX=$((IDX + 1))
done
sleep 0.6

# Wave 3 — low boom, kill everything
sfx "$SFX/boom-low.wav"
sleep 0.05
$W cmd desktop.clear-all 2>&1 >/dev/null
sleep 0.6

# THE BIG ONE — empty desktop, final boom
sfx "$SFX/boom-final.wav"
sleep 1.2

# ────────────────────────────────────────────────────────
# PHASE 7: FIN — shark + title card on empty black
# ────────────────────────────────────────────────────────

sfx "$VOICE_DIR/v-fin.wav"
echo "  Phase 7: FIN"

$W theme.set --name wibwob-dark 2>&1 >/dev/null
sleep 0.5

# Micromelody starts — shark and title timed to the notes
sfx "$SFX/fin-melody.wav"

# Note 1 (Bb4, t=0.0s) — shark swims in
$W primer.open --filePath "$JGS/shark-0000-2.txt" --x 70 --y 12 2>&1 >/dev/null
sleep 0.5

# Note 2 (Gb4, t=0.5s) — fin. appears
$W figlet.open --text "fin." --font small 2>&1 >/dev/null
sleep 0.5

# Position FIN under the shark
FIN_ID=$($W windows 2>/dev/null | jq -r '.[] | select(.appType=="wibwob.figlet") | .id')
[ -n "$FIN_ID" ] && batch "{\"ops\":[{\"id\":$FIN_ID,\"left\":80,\"top\":28,\"width\":30,\"height\":7}]}"

sleep 2.0
echo "    ↳ 🦈 fin."

$W screenshot > "$DIR/fin.txt" 2>/dev/null

# Clear for loop
sleep 0.5
$W cmd desktop.clear-all 2>&1 >/dev/null

echo ""
echo "═══ CREATURE WORD BOMB (SFX) COMPLETE ═══"
echo "8 phases: INTRO → MENAGERIE → CORRUPTION → SHEAR → DEEP GLITCH → WORD BOMB → DESTRUCTION → FIN"

# ── Render mixed audio track from logged cues ──
if [ -f "$CUES_FILE" ]; then
  NCUES=$(wc -l < "$CUES_FILE" | tr -d ' ')
  echo "Rendering $NCUES SFX cues → soundtrack.mp3"
  uv run scratch/cli-experiments/mix-sfx-track.py "$CUES_FILE" "$DIR/soundtrack.mp3" 2>&1
fi

# ── Export pipeline: .cast → .gif, .cast + .mp3 → .mp4 ──
if [ "$DO_EXPORT" = true ] && [ -f "$DIR/recording.cast" ]; then
  echo "Rendering .cast → .gif"
  agg "$DIR/recording.cast" "$DIR/recording.gif" --cols 180 --rows 51
  echo "  → $DIR/recording.gif"

  if [ -f "$DIR/soundtrack.mp3" ]; then
    echo "Compositing .gif + .mp3 → .mp4"
    ffmpeg -y -i "$DIR/recording.gif" -i "$DIR/soundtrack.mp3" \
      -c:v libx264 -pix_fmt yuv420p -crf 23 \
      -c:a aac -b:a 192k -shortest \
      "$DIR/creature-word-bomb.mp4" 2>/dev/null
    echo "  → $DIR/creature-word-bomb.mp4"
  fi
fi

echo "Files in $DIR/"
ls -la "$DIR/"
